@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

abstract class Vehicle {
  + VehicleNumber : string
}

class Truck {
  + Weight : float
}

class Car {
  + Seats : int
}

class Van {}

class Order {
  + OriginLocation : string
  + DestinationLocation : string
  + ExecutionDate : date
}

Location "1" *-- "1..*" Driver
Location "1" *-- "1..*" Vehicle
Vehicle --|> Truck
Vehicle --|> Car
Vehicle --|> Van

Driver "1" -- "0..1" Order
Order "1..*" -- "1" Driver

Driver "0..1" -- "1..*" Vehicle

